create table if not exists conversations (id bigserial primary key, organization_id uuid not null references organizations(id), subject text not null, contact_id bigint references contacts(id) on delete set null, client_id bigint references clients(id) on delete set null, channel text not null default 'internal' check (channel in ('internal','email','whatsapp')), status text not null default 'open' check (status in ('open','archived')), last_message_at timestamptz, unread_count int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists messages (id bigserial primary key, organization_id uuid not null references organizations(id), conversation_id bigint not null references conversations(id) on delete cascade, author_user_id uuid references users(id) on delete set null, direction text not null check (direction in ('in','out')), body text not null, read_at timestamptz, created_at timestamptz not null default now());
create index if not exists conversations_organization_id_idx on conversations(organization_id);
create index if not exists messages_organization_id_idx on messages(organization_id);
create index if not exists messages_conversation_id_idx on messages(conversation_id);
